insert into aegis.risk_definitions (id, name, description, body_region, criteria, source_document, validation_status) values
  ('bone_resorption', 'Alteración de la remodelación ósea', 'Riesgo de resorción ósea elevada en microgravedad.', 'skeleton', 'Baja actividad de fuerza + HRV deteriorada + fase hormonal desfavorable + posible deshidratación (spec 3.1, kb 3.1). Medición activada: CTX-I (± P1NP).', 'Sistema_Monitorizacion_Predictiva_Astronautas.docx (NASA Space Apps, nov. 2026)', 'design_hypothesis'),
  ('renal_stones', 'Riesgo de formación de cálculos renales', 'Hipercalciuria ligada a resorción ósea, deshidratación y desequilibrio electrolítico.', 'kidneys', 'Hidratación insuficiente + desequilibrio electrolítico + indicios de movilización ósea + bajo volumen urinario o pH alterado (spec 3.2, kb 3.2). Medición activada: perfil urinario.', 'Sistema_Monitorizacion_Predictiva_Astronautas.docx (NASA Space Apps, nov. 2026)', 'design_hypothesis'),
  ('inflammation_recovery', 'Alteración inflamatoria, inmunitaria o de recuperación', 'Inflamación, infección o sobreentrenamiento / fatiga acumulada.', 'metabolic', 'Cortisol elevado mantenido + HRV baja + sueño fragmentado + lactato de recuperación lento; temperatura elevada + FC en reposo alta + malestar (spec 3.3, kb 3.3-3.4). Medición activada: IL-6 / PCR.', 'Sistema_Monitorizacion_Predictiva_Astronautas.docx (NASA Space Apps, nov. 2026)', 'design_hypothesis'),
  ('cardiovascular_orthostatic', 'Alteración cardiovascular u ortostática', 'Desacondicionamiento cardiovascular e intolerancia ortostática.', 'heart', 'FC en reposo elevada + HRV baja + cambios de temperatura + hidratación alterada (spec 3.4). Medición activada: presión arterial y evaluación según protocolo de misión.', 'Sistema_Monitorizacion_Predictiva_Astronautas.docx (NASA Space Apps, nov. 2026)', 'design_hypothesis')
