insert into aegis.clinical_protocols (id, risk_id, title, trigger_rule, alert_level, category, recommendation, applies_to, source_document, validation_status) values
  ('hrv.yellow.exercise', 'inflammation_recovery', 'HRV / FC en reposo: alerta amarilla', '{"any": [{"biomarker": "hrv", "feature": "daily_pct_change_vs_initial", "between": [-25, -15], "sustained_days": 2}, {"biomarker": "heart_rate", "feature": "daily_delta_vs_initial", "between": [3, 5], "sustained_days": 2}]}'::jsonb, 'yellow', 'exercise', 'Reducir volumen/intensidad 20-30% (24-48 h). Recuperación activa.', '{}'::jsonb, 'kb 2.1 · document', 'pending_medical_review'),
  ('hrv.yellow.nutritional', 'inflammation_recovery', 'HRV / FC en reposo: alerta amarilla', '{"any": [{"biomarker": "hrv", "feature": "daily_pct_change_vs_initial", "between": [-25, -15], "sustained_days": 2}, {"biomarker": "heart_rate", "feature": "daily_delta_vs_initial", "between": [3, 5], "sustained_days": 2}]}'::jsonb, 'yellow', 'nutritional', 'CH + proteína post-esfuerzo. Evitar déficit calórico.', '{}'::jsonb, 'kb 2.1 · document', 'pending_medical_review'),
  ('hrv.yellow.pharmacological', 'inflammation_recovery', 'HRV / FC en reposo: alerta amarilla', '{"any": [{"biomarker": "hrv", "feature": "daily_pct_change_vs_initial", "between": [-25, -15], "sustained_days": 2}, {"biomarker": "heart_rate", "feature": "daily_delta_vs_initial", "between": [3, 5], "sustained_days": 2}]}'::jsonb, 'yellow', 'pharmacological', 'Melatonina si hay sueño pobre asociado.', '{}'::jsonb, 'kb 2.1 · document', 'pending_medical_review'),
  ('hrv.orange.exercise', 'inflammation_recovery', 'HRV / FC en reposo: alerta naranja', '{"any": [{"biomarker": "hrv", "feature": "daily_pct_change_vs_initial", "between": [-40, -25], "sustained_days": 2}, {"biomarker": "heart_rate", "feature": "daily_delta_vs_initial", "between": [5, 8], "sustained_days": 2}]}'::jsonb, 'orange', 'exercise', 'Reducción 40-60% o día de descarga. Evitar alta intensidad.', '{}'::jsonb, 'kb 2.1 · document', 'pending_medical_review'),
  ('hrv.orange.nutritional', 'inflammation_recovery', 'HRV / FC en reposo: alerta naranja', '{"any": [{"biomarker": "hrv", "feature": "daily_pct_change_vs_initial", "between": [-40, -25], "sustained_days": 2}, {"biomarker": "heart_rate", "feature": "daily_delta_vs_initial", "between": [5, 8], "sustained_days": 2}]}'::jsonb, 'orange', 'nutritional', 'Superávit calórico moderado + más CH y proteína. Electrolitos.', '{}'::jsonb, 'kb 2.1 · document', 'pending_medical_review'),
  ('hrv.orange.pharmacological', 'inflammation_recovery', 'HRV / FC en reposo: alerta naranja', '{"any": [{"biomarker": "hrv", "feature": "daily_pct_change_vs_initial", "between": [-40, -25], "sustained_days": 2}, {"biomarker": "heart_rate", "feature": "daily_delta_vs_initial", "between": [5, 8], "sustained_days": 2}]}'::jsonb, 'orange', 'pharmacological', 'Melatonina. Limitar estimulantes.', '{}'::jsonb, 'kb 2.1 · document', 'pending_medical_review'),
  ('hrv.red.exercise', 'inflammation_recovery', 'HRV: alerta roja (posible overreaching)', '{"all": [{"biomarker": "hrv", "feature": "daily_pct_change_vs_initial", "below": -40, "sustained_days": 2}, {"symptom_any": ["fatigue", "malaise"]}]}'::jsonb, 'red', 'exercise', 'Parar entrenamiento intenso. Solo recuperación.', '{}'::jsonb, 'kb 2.1 · document', 'pending_medical_review'),
  ('hrv.red.nutritional', 'inflammation_recovery', 'HRV: alerta roja (posible overreaching)', '{"all": [{"biomarker": "hrv", "feature": "daily_pct_change_vs_initial", "below": -40, "sustained_days": 2}, {"symptom_any": ["fatigue", "malaise"]}]}'::jsonb, 'red', 'nutritional', 'Priorizar energía y sueño.', '{}'::jsonb, 'kb 2.1 · document', 'pending_medical_review'),
  ('hrv.red.pharmacological', 'inflammation_recovery', 'HRV: alerta roja (posible overreaching)', '{"all": [{"biomarker": "hrv", "feature": "daily_pct_change_vs_initial", "below": -40, "sustained_days": 2}, {"symptom_any": ["fatigue", "malaise"]}]}'::jsonb, 'red', 'pharmacological', 'Melatonina.', '{}'::jsonb, 'kb 2.1 · document', 'pending_medical_review'),
  ('hrv.red.escalation', 'inflammation_recovery', 'HRV: alerta roja (posible overreaching)', '{"all": [{"biomarker": "hrv", "feature": "daily_pct_change_vs_initial", "below": -40, "sustained_days": 2}, {"symptom_any": ["fatigue", "malaise"]}]}'::jsonb, 'red', 'escalation', 'Escalar a médico de vuelo si no mejora en 48-72 h.', '{}'::jsonb, 'kb 2.1 · document', 'pending_medical_review'),
  ('temperature.yellow.nutritional', 'inflammation_recovery', 'Temperatura: elevación sostenida 0,5-0,8 °C', '{"biomarker": "temperature", "feature": "daily_delta_vs_initial", "between": [0.5, 0.8], "sustained_days": 2, "cycle_aware": true}'::jsonb, 'yellow', 'nutritional', 'Aumentar hidratación + electrolitos.', '{}'::jsonb, 'kb 2.3 · document', 'pending_medical_review'),
  ('temperature.yellow.exercise', 'inflammation_recovery', 'Temperatura: elevación sostenida 0,5-0,8 °C', '{"biomarker": "temperature", "feature": "daily_delta_vs_initial", "between": [0.5, 0.8], "sustained_days": 2, "cycle_aware": true}'::jsonb, 'yellow', 'exercise', 'Reducir carga térmica del ejercicio.', '{}'::jsonb, 'kb 2.3 · document', 'pending_medical_review'),
  ('temperature.yellow.pharmacological', 'inflammation_recovery', 'Temperatura: elevación sostenida 0,5-0,8 °C', '{"biomarker": "temperature", "feature": "daily_delta_vs_initial", "between": [0.5, 0.8], "sustained_days": 2, "cycle_aware": true}'::jsonb, 'yellow', 'pharmacological', 'Observar; paracetamol si aparece molestia.', '{}'::jsonb, 'kb 2.3 · document', 'pending_medical_review'),
